class Solution:
    def sumDigitDifferences(self, nums: List[int]) -> int:
        n = len(nums)
        vals = nums[:]
        ans = 0
        all_pairs = n * (n - 1) // 2
        while vals[0]:
            cnt = [0] * 10
            for i in range(n):
                cnt[vals[i] % 10] += 1
                vals[i] //= 10
            ans += all_pairs - sum(c * (c - 1) // 2 for c in cnt)
        return ans

