class Solution {
public:
    long long sumDigitDifferences(vector<int>& nums) {
        int n = nums.size();
        vector<int> vals = nums;
        long long ans = 0, allPairs = 1LL * n * (n - 1) / 2;
        while (vals[0]) {
            long long cnt[10] = {0};
            for (int i = 0; i < n; i++) {
                cnt[vals[i] % 10]++;
                vals[i] /= 10;
            }
            long long same = 0;
            for (int d = 0; d < 10; d++) same += cnt[d] * (cnt[d] - 1) / 2;
            ans += allPairs - same;
        }
        return ans;
    }
};

