var sumDigitDifferences = function(nums) {
    const n = nums.length;
    const vals = [...nums];
    let ans = 0;
    const allPairs = n * (n - 1) / 2;
    while (vals[0] > 0) {
        const cnt = Array(10).fill(0);
        for (let i = 0; i < n; i++) {
            cnt[vals[i] % 10]++;
            vals[i] = Math.floor(vals[i] / 10);
        }
        let same = 0;
        for (const c of cnt) same += c * (c - 1) / 2;
        ans += allPairs - same;
    }
    return ans;
};

