class Solution {
    public long sumDigitDifferences(int[] nums) {
        int n = nums.length;
        String[] strs = new String[n];
        for (int i = 0; i < n; i++) strs[i] = Integer.toString(nums[i]);
        long allPairs = (long) n * (n - 1) / 2, ans = 0;
        for (int pos = 0; pos < strs[0].length(); pos++) {
            long[] cnt = new long[10];
            for (String t : strs) cnt[t.charAt(pos) - '0']++;
            long same = 0;
            for (int d = 0; d < 10; d++) same += cnt[d] * (cnt[d] - 1) / 2;
            ans += allPairs - same;
        }
        return ans;
    }
}

